head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col1": "1",
        "custom": "19941005",
        "col2": "1"
    }, {
        "col1": "1",
        "custom": "v3",
        "col2": "1"
    }, {
        "col1": "1",
        "custom": "v1",
        "col2": "1"
    }];
    dataList1.setJSON(jsonData);
    var jsonData1 = [{
        "col1": "v1",
        "col2": "lb1"
    }, {
        "col1": "v2",
        "col2": "lb2"
    }, {
        "col1": "v3",
        "col2": "lb3"
    }];
    dataList2.setJSON(jsonData1);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    ++sIdx;
    select1.addItem("value" + sIdx, "label" + sIdx);
};
scwin.fn1 = function() {
    gridView1.setCellInputType(0, "custom", {
        inputType: "calendar",
        options: {
            imageSrc: "",
            viewType: "icon"
        }
    });
}
scwin.trigger3_onclick = function(e) {
    scwin.fn1();
};
scwin.__hasClass = function() {
    var classList = WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1__dynamic_calendar_0_1').className;
    return classList.indexOf('gridBodyDefault') == -1;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_1').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "scwin.__hasClass()", "true");
    WebSquare.wUnit.addCommand('pause', '500');
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.sIdx = 0;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
